package dev.reliefgrid;
import dev.reliefgrid.engine.AllocationEngine;import dev.reliefgrid.model.Category;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class AllocationEngineTest {
 private AllocationEngine.Input fixture(){return new AllocationEngine.Input(List.of(new AllocationEngine.Place(1,16.5,80.6,true),new AllocationEngine.Place(2,16.51,80.62,false)),List.of(new AllocationEngine.Stock(1,1,Category.WATER,4),new AllocationEngine.Stock(2,2,Category.FOOD,3)),List.of(new AllocationEngine.Demand(1,1,Category.WATER,10,5,1),new AllocationEngine.Demand(2,2,Category.WATER,3,2,2),new AllocationEngine.Demand(3,2,Category.FOOD,7,4,3)),List.of(new AllocationEngine.Carrier(1,1,3,true),new AllocationEngine.Carrier(2,2,2,true)));}
 @Test void respectsStockVolunteerAndDemandCaps(){var in=fixture();var r=AllocationEngine.optimized(in);assertTrue(r.allocated()<=5);assertTrue(r.picks().stream().filter(p->p.stockId()==1).mapToInt(AllocationEngine.Pick::quantity).sum()<=4);assertTrue(r.picks().stream().filter(p->p.stockId()==2).mapToInt(AllocationEngine.Pick::quantity).sum()<=3);assertTrue(r.picks().stream().filter(p->p.carrierId()==1).mapToInt(AllocationEngine.Pick::quantity).sum()<=3);assertTrue(r.picks().stream().filter(p->p.carrierId()==2).mapToInt(AllocationEngine.Pick::quantity).sum()<=2);}
 @Test void respectsCategory(){var r=AllocationEngine.optimized(fixture());assertTrue(r.picks().stream().allMatch(p->(p.stockId()==2)==(p.demandId()==3)));}
 @Test void doesNotInventStock(){var in=fixture();var zero=new AllocationEngine.Input(in.places(),List.of(new AllocationEngine.Stock(1,1,Category.WATER,0)),in.demands(),in.carriers());assertEquals(0,AllocationEngine.optimized(zero).allocated());}
 @Test void highPriorityPreferred(){var in=new AllocationEngine.Input(List.of(new AllocationEngine.Place(1,16,80,false)),List.of(new AllocationEngine.Stock(1,1,Category.WATER,1)),List.of(new AllocationEngine.Demand(1,1,Category.WATER,1,1,1),new AllocationEngine.Demand(2,1,Category.WATER,1,5,2)),List.of(new AllocationEngine.Carrier(1,1,1,true)));var result=AllocationEngine.optimized(in);assertEquals(2,result.picks().get(0).demandId());}
 @Test void baselineAndOptimizerProduceNonnegativeQuantities(){for(var r:List.of(AllocationEngine.baseline(fixture()),AllocationEngine.optimized(fixture())))assertTrue(r.picks().stream().allMatch(x->x.quantity()>0&&x.distanceKm()>=0));}
}
